window.PIP_CSS=".pip .tail,.pip .tail-soft,.pip .tilt,.pip .nod,.pip .watch,.pip .bob,.pip .lids,.pip .breathe,.pip .breathe-deep,.pip .puff,.pip .hop,.pip .rock,.pip .shadow-hop,.pip .wave-l,.pip .wave-r,.pip .twinkle,.pip .spin,.pip .roll,.pip .stretch,.pip .yawn,.pip .swipe,.pip .swing,.pip .page,.pip .type-l,.pip .type-r,.pip .zz,.pip .heart{transform-box:fill-box}\n.pip .tail{transform-origin:0% 100%}.pip .tail-soft{transform-origin:100% 20%}\n.pip .tilt,.pip .nod,.pip .watch,.pip .bob{transform-origin:50% 90%}\n.pip .lids{transform-origin:50% 50%;transform:scaleY(0)}\n.pip .breathe,.pip .breathe-deep,.pip .puff{transform-origin:50% 100%}\n.pip .hop,.pip .rock{transform-origin:50% 100%}.pip .shadow-hop{transform-origin:50% 50%}\n.pip .wave-l{transform-origin:80% 100%}.pip .wave-r{transform-origin:20% 100%}\n.pip .twinkle,.pip .spin,.pip .roll{transform-origin:50% 50%}\n.pip .stretch{transform-origin:100% 100%}.pip .yawn{transform-origin:50% 0%}\n.pip .swipe{transform-origin:100% 0%}.pip .swing{transform-origin:50% 0%}.pip .page{transform-origin:0% 50%}\n.pip .type-l,.pip .type-r{transform-origin:50% 0%}\n@media (prefers-reduced-motion:no-preference){\n.moving .tail{animation:nlSway 3.2s ease-in-out infinite}\n.moving .tail-soft{animation:nlSoft 4.4s ease-in-out infinite}\n.moving .lids{animation:nlBlink 5.2s infinite}\n.moving .tilt{animation:nlTilt 5.5s ease-in-out infinite}\n.moving .nod{animation:nlNod 4.4s ease-in-out infinite}\n.moving .watch{animation:nlWatch 1.4s ease-in-out infinite}\n.moving .bob{animation:nlBob 1.8s ease-in-out infinite}\n.moving .breathe{animation:nlBreathe 3.6s ease-in-out infinite}\n.moving .breathe-deep{animation:nlBreatheDeep 4.4s ease-in-out infinite}\n.moving .puff{animation:nlPuff 2.2s ease-in-out infinite}\n.moving .hop{animation:nlHop 1.1s cubic-bezier(.3,0,.4,1) infinite}\n.moving .shadow-hop{animation:nlShadow 1.1s cubic-bezier(.3,0,.4,1) infinite}\n.moving .wave-l{animation:nlWaveL .55s ease-in-out infinite alternate}\n.moving .wave-r{animation:nlWaveR .55s ease-in-out infinite alternate}\n.moving .twinkle{animation:nlTwinkle 1.8s ease-in-out infinite}\n.moving .t2{animation-delay:-.6s}.moving .t3{animation-delay:-1.2s}\n.moving .zz{animation:nlFloat 2.8s ease-in-out infinite}\n.moving .stretch{animation:nlStretch 3.4s ease-in-out infinite}\n.moving .yawn{animation:nlYawn 3.4s ease-in-out infinite}\n.moving .swipe{animation:nlSwipe 1.5s ease-in-out infinite}\n.moving .roll{animation:nlRoll 1.5s ease-in-out infinite}\n.moving .rock{animation:nlRock 2.6s ease-in-out infinite}\n.moving .heart{animation:nlRise 2.6s ease-in infinite}\n.moving .spin{animation:nlSpin 1.1s linear infinite}\n.moving .type-l{animation:nlType .36s ease-in-out infinite alternate}\n.moving .type-r{animation:nlType .36s ease-in-out infinite alternate-reverse}\n.moving .swing{animation:nlSwing 1.8s ease-in-out infinite}\n.moving .page{animation:nlPage 4.8s ease-in-out infinite}\n}\n@keyframes nlSway{0%,100%{transform:rotate(0)}50%{transform:rotate(8deg)}}\n@keyframes nlSoft{0%,100%{transform:rotate(0)}50%{transform:rotate(-3deg)}}\n@keyframes nlBlink{0%,92%,100%{transform:scaleY(0)}95%{transform:scaleY(1)}}\n@keyframes nlTilt{0%,100%{transform:rotate(0)}30%{transform:rotate(-4deg)}65%{transform:rotate(3deg)}}\n@keyframes nlNod{0%,100%{transform:translateY(0)}50%{transform:translateY(2px) rotate(-2deg)}}\n@keyframes nlWatch{0%,100%{transform:rotate(0)}35%{transform:rotate(-6deg)}}\n@keyframes nlBob{0%,100%{transform:translateY(0)}50%{transform:translateY(2.5px)}}\n@keyframes nlBreathe{0%,100%{transform:scale(1)}50%{transform:scale(1.025,1.04)}}\n@keyframes nlBreatheDeep{0%,100%{transform:scale(1)}50%{transform:scale(1.03,1.07)}}\n@keyframes nlPuff{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}\n@keyframes nlHop{0%,100%{transform:translateY(0) scale(1.04,.96)}15%{transform:translateY(0) scale(1)}50%{transform:translateY(-16px) scale(.98,1.03)}85%{transform:translateY(0) scale(1)}}\n@keyframes nlShadow{0%,100%{transform:scale(1);opacity:.12}50%{transform:scale(.72);opacity:.07}}\n@keyframes nlWaveL{from{transform:rotate(-8deg)}to{transform:rotate(10deg)}}\n@keyframes nlWaveR{from{transform:rotate(8deg)}to{transform:rotate(-10deg)}}\n@keyframes nlTwinkle{0%,100%{transform:scale(.6);opacity:.4}50%{transform:scale(1.15);opacity:1}}\n@keyframes nlFloat{0%{transform:translate(0,0);opacity:0}25%{opacity:1}100%{transform:translate(6px,-16px);opacity:0}}\n@keyframes nlStretch{0%,100%{transform:scaleX(1)}50%{transform:scaleX(1.05) translateY(2px)}}\n@keyframes nlYawn{0%,20%,100%{transform:scaleY(.35)}50%,70%{transform:scaleY(1.1)}}\n@keyframes nlSwipe{0%,100%{transform:rotate(0)}30%{transform:rotate(-22deg)}45%{transform:rotate(4deg)}}\n@keyframes nlRoll{0%,28%,100%{transform:translateX(0) rotate(0)}55%{transform:translateX(-7px) rotate(-40deg)}}\n@keyframes nlRock{0%,100%{transform:rotate(-3deg)}50%{transform:rotate(3deg)}}\n@keyframes nlRise{0%{transform:translateY(8px) scale(.6);opacity:0}30%{opacity:1}100%{transform:translateY(-22px) scale(1);opacity:0}}\n@keyframes nlSpin{to{transform:rotate(360deg)}}\n@keyframes nlType{from{transform:translateY(0)}to{transform:translateY(-3px)}}\n@keyframes nlSwing{0%,100%{transform:rotate(-9deg)}50%{transform:rotate(9deg)}}\n@keyframes nlPage{0%,70%,100%{transform:scaleX(1)}80%{transform:scaleX(.2)}90%{transform:scaleX(1)}}";
